from bagimlilik import kurulum_sirasi, DonguHatasi

# 1. Basit doğrusal bağımlılık (A -> B)
deps_1 = {"A": ["B"]}
# Beklenen: B, A (Eğer A, B tanımlıysa. Tanımlı olmadığı için sadece B, A olmalı. Ama dep[A]=[B] yani B A'dan önce gelir.
# Düzeltme: deps[A] = [B] demek B, A'nın bağımlısıdır. Yön: B -> A. Sıra: [B, A]
print("Test 1 (B->A): ", kurulum_sirasi(deps_1))

# 2. Birden fazla başlangıç noktası ve alfabetik sıralama (A ve B bağımsız)
deps_2 = {"A": [], "B": []}
# Beklenen: [A, B]
print("Test 2 (A, B): ", kurulum_sirasi(deps_2))

# 3. Karmaşık bağımlılık ve alfabetik öncelik (A, C'den önce B gelir)
deps_3 = {"C": [], "A": ["C"], "B": ["C"]}
# Beklenen: [C, A, B] veya [C, B, A]. Alfabetik kural gereği: [C, A, B]
print("Test 3 (C->A, C->B): ", kurulum_sirasi(deps_3))

# 4. Döngü tespiti (A -> B -> A)
deps_4 = {"A": ["B"], "B": ["A"]}
print("Test 4 (A<->B) - Hata bekleniyor:")
try:
    kurulum_sirasi(deps_4)
except DonguHatasi as e:
    print("Başarılı: Döngü hatası yakalandı. Döngü: ", e.dongu)

# 5. Kendine bağımlılık (X -> X)
deps_5 = {"X": ["X"]}
print("Test 5 (X->X) - Hata bekleniyor:")
try:
    kurulum_sirasi(deps_5)
except DonguHatasi as e:
    print("Başarılı: Döngü hatası yakalandı. Döngü: ", e.dongu)

# 6. Bağımlılık olarak geçen ancak anahtar olmayan paket (Z)
deps_6 = {"A": ["Z"]}
# Beklenen: [Z, A]
print("Test 6 (Z, A): ", kurulum_sirasi(deps_6))
